Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='protondrive', at=datetime(2026, 9, 25, 0, 0, 0), actor='assistant', title="Proton Drive is the secretary's by permission: two reads, two writes, an allow-list and redacted ID numbers", body="*Proton Drive is the secretary's by permission* (2026-09-25, `docs/SECRETARYDOCS-PLAN-2026-09-25.md`): the CLI is reached only through a closed enum of two reads (list, download) and two writes (create-folder, upload) that `ProtonDrive::keep` alone uses, a file outside a `[secretary] drive_allow` folder is read only on a tap, and every SSN/ITIN/TIN/EIN is `redact`ed (`Redacted` is the only type a read answers in) before a transcript or a model sees it; the triage agent gets no Drive.", rationale='Decided 2026-09-25 (docs/SECRETARYDOCS-PLAN-2026-09-25.md).', supersedes=()))